abstract class TicketHandler {
  private next: TicketHandler | null = null;
  setNext(handler: TicketHandler) { this.next = handler; return handler; }

  handle(ticket: Ticket) {
    if (this.canHandle(ticket)) {
      return this.process(ticket);
    }
    return this.next?.handle(ticket) ?? "unhandled";
  }

  protected abstract canHandle(ticket: Ticket): boolean;
  protected abstract process(ticket: Ticket): string;
}

class BillingHandler extends TicketHandler {
  protected canHandle(t: Ticket) { return t.category === "billing"; }
  protected process(t: Ticket) { return billingTeam.handle(t); }
}
class EngineeringHandler extends TicketHandler {
  protected canHandle(t: Ticket) { return t.category === "technical"; }
  protected process(t: Ticket) { return engineeringTeam.handle(t); }
}

